#include "cryptoutils.h"
int main(void){char mode,text[2048];printf("Encrypt (E) or decrypt (D)? ");if(scanf(" %c",&mode)!=1)return 1;getchar();cu_readline("Text: ",text,sizeof text);mode=(char)toupper((unsigned char)mode);if(mode!='E'&&mode!='D'){puts("Invalid mode.");return 1;}printf("Enter one key number 0..25 for each alphabetic letter (space-separated):\n");for(size_t i=0;text[i];i++){unsigned char c=(unsigned char)text[i];if(isalpha(c)){int k;if(scanf("%d",&k)!=1||k<0||k>25){puts("Invalid key number.");return 1;}int base=islower(c)?'a':'A';text[i]=(char)(base+cu_mod((c-base)+(mode=='E'?k:-k),26));}}printf("Result: %s\n",text);puts("For a true one-time pad, the key stream must be uniformly random, as long as the message, kept secret, and never reused.");return 0;}
